//! Synthetic images (generated by code, never committed) and an HTTP gallery scenario for the
//! Pictures view: PNG, JPEG, GIF, WebP, BMP, ICO and SVG files, a truncated JPEG, an image
//! downloaded twice, a tracking pixel, and bodies that must not become objects (page, script,
//! login form, an HTML error labelled as an image).
//!
//! The client (192.168.1.24) and servers (198.51.100.31, 198.51.100.32) are not used by the
//! other scenarios, so their connections never collide with them when traffic is merged.

use std::io::Cursor;

use image::codecs::gif::GifEncoder;
use image::codecs::jpeg::JpegEncoder;
use image::{ImageFormat, Rgb, RgbImage, Rgba, RgbaImage};

use crate::packet::Host;
use crate::scenario::{Scenario, TcpOptions, TcpSession};
use crate::time::NS_PER_MS;

/// Colour themes of [`scene`] (sky top, sky bottom, ground, sun).
const THEMES: [[[u8; 3]; 4]; 6] = [
    [
        [38, 70, 140],
        [150, 190, 230],
        [52, 110, 72],
        [250, 214, 110],
    ],
    [[90, 40, 90], [240, 150, 110], [70, 60, 80], [255, 230, 160]],
    [[20, 30, 60], [60, 80, 130], [30, 40, 50], [235, 235, 220]],
    [
        [120, 170, 210],
        [220, 235, 245],
        [200, 180, 130],
        [255, 250, 220],
    ],
    [
        [30, 90, 100],
        [120, 200, 190],
        [40, 70, 60],
        [250, 200, 120],
    ],
    [
        [160, 80, 40],
        [250, 200, 140],
        [110, 70, 40],
        [255, 240, 200],
    ],
];

/// Linear blend from `from` (at `step` 0) to `to` (at `steps`).
fn mix(from: [u8; 3], to: [u8; 3], step: u32, steps: u32) -> [u8; 3] {
    let steps = steps.max(1);
    let step = step.min(steps);
    let channel = |lo: u8, hi: u8| {
        let value = (u32::from(lo) * (steps - step) + u32::from(hi) * step) / steps;
        u8::try_from(value).unwrap_or(u8::MAX)
    };
    [
        channel(from[0], to[0]),
        channel(from[1], to[1]),
        channel(from[2], to[2]),
    ]
}

/// A small landscape (sky gradient, sun, hills), identical for identical arguments.
///
/// # Panics
/// If a dimension is zero.
pub fn scene(width: u32, height: u32, theme: usize) -> RgbImage {
    assert!(width > 0 && height > 0, "image dimensions must be non-zero");
    let [top, bottom, ground, sun] = THEMES[theme % THEMES.len()];
    let (w, h) = (i64::from(width), i64::from(height));
    let (cx, cy, r) = (
        w * (2 + i64::try_from(theme % 5).unwrap_or(0)) / 8,
        h / 3,
        h.min(w) / 7 + 1,
    );
    RgbImage::from_fn(width, height, |x, y| {
        let (xi, yi) = (i64::from(x), i64::from(y));
        // Hills: two sine-like bumps from integer arithmetic.
        let phase = (xi * 360 / w.max(1) + i64::try_from(theme).unwrap_or(0) * 47) % 360;
        let bump = (phase - 180).abs();
        let horizon = h * 3 / 5 + (bump - 90) * h / 1400;
        let color = if yi > horizon {
            mix(
                ground,
                [10, 20, 10],
                u32::try_from(yi - horizon).unwrap_or(0),
                height,
            )
        } else if (xi - cx).pow(2) + (yi - cy).pow(2) <= r * r {
            sun
        } else {
            mix(top, bottom, y, height)
        };
        Rgb(color)
    })
}

/// [`scene`] as PNG.
pub fn png(width: u32, height: u32, theme: usize) -> Vec<u8> {
    encode(&scene(width, height, theme), ImageFormat::Png)
}

/// [`scene`] as baseline JPEG (quality 85).
pub fn jpeg(width: u32, height: u32, theme: usize) -> Vec<u8> {
    let mut out = Vec::new();
    let img = scene(width, height, theme);
    let mut enc = JpegEncoder::new_with_quality(&mut out, 85);
    // Encoding into memory cannot fail for a valid image.
    enc.encode_image(&img).unwrap_or_default();
    out
}

/// [`scene`] as GIF (palette quantized by the encoder).
pub fn gif(width: u32, height: u32, theme: usize) -> Vec<u8> {
    let mut out = Vec::new();
    {
        let rgba = image::DynamicImage::ImageRgb8(scene(width, height, theme)).into_rgba8();
        let mut enc = GifEncoder::new_with_speed(&mut out, 30);
        enc.encode(
            rgba.as_raw(),
            width,
            height,
            image::ExtendedColorType::Rgba8,
        )
        .unwrap_or_default();
    }
    out
}

/// [`scene`] as lossless WebP.
pub fn webp(width: u32, height: u32, theme: usize) -> Vec<u8> {
    let rgba = image::DynamicImage::ImageRgb8(scene(width, height, theme)).into_rgba8();
    encode_rgba(&rgba, ImageFormat::WebP)
}

/// [`scene`] as BMP.
pub fn bmp(width: u32, height: u32, theme: usize) -> Vec<u8> {
    encode(&scene(width, height, theme), ImageFormat::Bmp)
}

/// A square icon (rounded tile with a mark), as ICO.
pub fn ico(size: u32) -> Vec<u8> {
    let s = i64::from(size.max(1));
    let img = RgbaImage::from_fn(size.max(1), size.max(1), |x, y| {
        let (x, y) = (i64::from(x), i64::from(y));
        let edge = s / 6;
        let corner = (x < edge || x >= s - edge) && (y < edge || y >= s - edge);
        if corner {
            Rgba([0, 0, 0, 0])
        } else if (x - s / 2).abs() + (y - s / 2).abs() < s / 4 {
            Rgba([250, 250, 250, 255])
        } else {
            Rgba([37, 99, 235, 255])
        }
    });
    encode_rgba(&img, ImageFormat::Ico)
}

/// A 1x1 transparent GIF (tracking pixel).
pub fn pixel_gif() -> Vec<u8> {
    let img = RgbaImage::from_pixel(1, 1, Rgba([0, 0, 0, 0]));
    encode_rgba(&img, ImageFormat::Gif)
}

/// A small SVG logo (text: never rasterized by NetSift, served for download only).
pub fn svg() -> Vec<u8> {
    b"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\
<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"120\" height=\"40\" viewBox=\"0 0 120 40\">\
<rect width=\"120\" height=\"40\" rx=\"6\" fill=\"#2563eb\"/>\
<text x=\"60\" y=\"26\" font-family=\"sans-serif\" font-size=\"16\" fill=\"#fff\" text-anchor=\"middle\">Example</text>\
</svg>\n"
        .to_vec()
}

/// A JPEG cut after `keep` bytes (still starts with the JPEG signature).
pub fn truncated_jpeg(width: u32, height: u32, keep: usize) -> Vec<u8> {
    let mut data = jpeg(width, height, 2);
    data.truncate(keep);
    data
}

/// A PNG whose header announces `width` x `height` pixels, with almost no data: decoding it
/// must be refused from the header (decompression bomb by dimensions).
pub fn dimension_bomb_png(width: u32, height: u32) -> Vec<u8> {
    let mut out = vec![0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a];
    let mut ihdr = Vec::with_capacity(13);
    ihdr.extend_from_slice(&width.to_be_bytes());
    ihdr.extend_from_slice(&height.to_be_bytes());
    ihdr.extend_from_slice(&[8, 2, 0, 0, 0]);
    let chunk = |out: &mut Vec<u8>, kind: &[u8; 4], data: &[u8]| {
        out.extend_from_slice(&u32::try_from(data.len()).unwrap_or(0).to_be_bytes());
        let mut crc = crc32fast::Hasher::new();
        crc.update(kind);
        crc.update(data);
        out.extend_from_slice(kind);
        out.extend_from_slice(data);
        out.extend_from_slice(&crc.finalize().to_be_bytes());
    };
    chunk(&mut out, b"IHDR", &ihdr);
    // zlib stream of a few zero bytes.
    chunk(
        &mut out,
        b"IDAT",
        &[0x78, 0x9c, 0x63, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01],
    );
    chunk(&mut out, b"IEND", &[]);
    out
}

fn encode(img: &RgbImage, format: ImageFormat) -> Vec<u8> {
    let mut out = Cursor::new(Vec::new());
    img.write_to(&mut out, format).unwrap_or_default();
    out.into_inner()
}

fn encode_rgba(img: &RgbaImage, format: ImageFormat) -> Vec<u8> {
    let mut out = Cursor::new(Vec::new());
    img.write_to(&mut out, format).unwrap_or_default();
    out.into_inner()
}

// ------------------------------------------------------------------------------------------
// HTTP gallery scenario
// ------------------------------------------------------------------------------------------

const ROUTER_MAC: [u8; 6] = [0x02, 0x00, 0x5e, 0x10, 0x00, 0x01];
const BROWSER: &str = "Mozilla/5.0 (X11; Linux x86_64; rv:128.0) Gecko/20100101 Firefox/128.0";

fn browser() -> Host {
    Host::v4([0x02, 0x00, 0x5e, 0x10, 0x00, 0x24], [192, 168, 1, 24])
}

fn images_server() -> Host {
    Host::v4(ROUTER_MAC, [198, 51, 100, 31])
}

fn cdn_server() -> Host {
    Host::v4(ROUTER_MAC, [198, 51, 100, 32])
}

fn get(s: &mut TcpSession<'_>, host: &str, path: &str, content_type: &str, body: &[u8]) {
    let req = format!(
        "GET {path} HTTP/1.1\r\nHost: {host}\r\nUser-Agent: {BROWSER}\r\nAccept: */*\r\n\r\n"
    );
    s.client_send(req.as_bytes());
    s.scenario().advance(2 * NS_PER_MS);
    let mut resp = format!(
        "HTTP/1.1 200 OK\r\nServer: nginx/1.24.0\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\n\r\n",
        body.len()
    )
    .into_bytes();
    resp.extend_from_slice(body);
    s.server_send(&resp);
    s.scenario().advance(3 * NS_PER_MS);
}

/// Distinct images stored by one [`gallery`] round (the duplicate counts once; the page,
/// script, form and fake image are not objects).
pub const GALLERY_OBJECTS: usize = 13;

/// One browsing session over two image servers (keep-alive connections).
pub fn gallery(sc: &mut Scenario) {
    let host = "images.example.test";
    let mut s = sc.tcp_open(browser(), images_server(), &TcpOptions::new(80));
    let page = b"<!doctype html><html><head><title>Gallery</title></head><body><h1>Gallery</h1></body></html>";
    get(&mut s, host, "/gallery/", "text/html; charset=utf-8", page);
    get(
        &mut s,
        host,
        "/gallery/app.js",
        "application/javascript",
        b"document.title = 'Gallery';\n",
    );
    let photos: [(&str, Vec<u8>, &str); 7] = [
        ("/gallery/harbour.jpg", jpeg(640, 420, 0), "image/jpeg"),
        ("/gallery/dusk.jpg", jpeg(480, 640, 1), "image/jpeg"),
        ("/gallery/night.png", png(400, 300, 2), "image/png"),
        ("/gallery/dunes.webp", webp(360, 240, 3), "image/webp"),
        ("/gallery/lagoon.gif", gif(240, 180, 4), "image/gif"),
        ("/gallery/canyon.bmp", bmp(200, 140, 5), "image/bmp"),
        ("/gallery/panorama.png", png(900, 240, 0), "image/png"),
    ];
    for (path, body, ct) in &photos {
        get(&mut s, host, path, ct, body);
    }
    // Served with a generic type: kept, the type comes from the content.
    get(
        &mut s,
        host,
        "/download?id=42",
        "application/octet-stream",
        &png(256, 256, 4),
    );
    // An HTML error page labelled as an image: not an object.
    get(
        &mut s,
        host,
        "/gallery/missing.png",
        "image/png",
        b"<html><body>Not found</body></html>",
    );
    // Login form (request body): never stored.
    let form = b"user=alice&password=correct-horse";
    let req = format!(
        "POST /login HTTP/1.1\r\nHost: {host}\r\nUser-Agent: {BROWSER}\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: {}\r\n\r\n",
        form.len()
    );
    let mut req = req.into_bytes();
    req.extend_from_slice(form);
    s.client_send(&req);
    s.server_send(b"HTTP/1.1 302 Found\r\nLocation: /gallery/\r\nContent-Length: 0\r\n\r\n");
    s.close();
    sc.advance(10 * NS_PER_MS);

    let cdn = "cdn.example.test";
    let mut s = sc.tcp_open(browser(), cdn_server(), &TcpOptions::new(80));
    get(&mut s, cdn, "/favicon.ico", "image/x-icon", &ico(32));
    get(&mut s, cdn, "/brand/logo.svg", "image/svg+xml", &svg());
    get(&mut s, cdn, "/t.gif?u=1", "image/gif", &pixel_gif());
    // Same content as on the images server: one object, two occurrences.
    get(
        &mut s,
        cdn,
        "/mirror/night.png",
        "image/png",
        &png(400, 300, 2),
    );
    get(
        &mut s,
        cdn,
        "/thumbs/tile.png",
        "image/png",
        &png(96, 96, 5),
    );
    // Complete at the HTTP level, but the file itself is cut: no thumbnail.
    get(
        &mut s,
        cdn,
        "/broken/cut.jpg",
        "image/jpeg",
        &truncated_jpeg(320, 240, 300),
    );
    s.close();
    sc.advance(10 * NS_PER_MS);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn images_are_valid_and_deterministic() {
        assert_eq!(png(32, 16, 1), png(32, 16, 1));
        assert!(png(32, 16, 1).starts_with(b"\x89PNG"));
        assert!(jpeg(32, 16, 1).starts_with(&[0xff, 0xd8, 0xff]));
        assert!(gif(32, 16, 1).starts_with(b"GIF8"));
        let w = webp(32, 16, 1);
        assert!(w.starts_with(b"RIFF") && &w[8..12] == b"WEBP");
        assert!(bmp(8, 8, 0).starts_with(b"BM"));
        assert!(ico(16).starts_with(&[0, 0, 1, 0]));
        assert!(pixel_gif().starts_with(b"GIF8"));
        for (data, format) in [
            (png(20, 10, 3), ImageFormat::Png),
            (jpeg(20, 10, 3), ImageFormat::Jpeg),
            (gif(20, 10, 3), ImageFormat::Gif),
            (webp(20, 10, 3), ImageFormat::WebP),
            (bmp(20, 10, 3), ImageFormat::Bmp),
        ] {
            let img = image::load_from_memory_with_format(&data, format).unwrap();
            assert_eq!((img.width(), img.height()), (20, 10), "{format:?}");
        }
        assert_eq!(truncated_jpeg(64, 64, 100).len(), 100);
        assert!(dimension_bomb_png(100_000, 100_000).len() < 100);
    }

    #[test]
    fn gallery_is_deterministic() {
        let mut a = Scenario::new();
        gallery(&mut a);
        let mut b = Scenario::new();
        gallery(&mut b);
        assert_eq!(a.packets(), b.packets());
        assert!(a.packets().len() > 50);
    }
}
